create or replace function public.admin_get_subscriber_history(_order_id uuid) returns table(payment_id uuid,payment_type text,amount numeric,reference text,status text,payment_date timestamptz,description text,installment_number integer,installment_status text,installment_amount_paid numeric,installment_amount_due numeric,documentation_name text) language plpgsql security definer set search_path=public as $$ begin if not is_admin(auth.uid()) then raise exception 'Admin access required'; end if; if not exists(select 1 from public.orders where id=_order_id) then raise exception 'Order not found'; end if; return query select pr.id,pr.type,pr.amount,pr.reference,pr.status,coalesce(pr.processed_at,pr.created_at),pr.description,oi.installment_number,oi.status,oi.amount_paid,oi.amount_due,case when lower(coalesce(pr.type,'')) like '%documentation%' then coalesce(pr.description,'Documentation Bundle') else null end from public.payment_requests pr left join public.order_installments oi on oi.payment_id=pr.related_payment_id and oi.order_id=_order_id where pr.user_id=(select user_id from public.orders where id=_order_id) and (pr.description ilike '%'||(select coalesce(customer_name,'') from public.orders where id=_order_id)||'%' or pr.related_payment_id in(select oi2.payment_id from public.order_installments oi2 where oi2.order_id=_order_id) or pr.reference=(select payment_reference from public.orders where id=_order_id)) order by coalesce(pr.processed_at,pr.created_at) desc; end; $$; grant execute on function public.admin_get_subscriber_history(uuid) to authenticated;
